function TheSonnet() {
  const sonnet = {
    title: { en: "Our Anthem - Blooming Sonnet", it: "Il Nostro Inno" },
    verses: [
      {
        type: "verse",
        verse: [
          {
            lineId: 1,
            en: "When seasons come, our hearts will bloom,",
            it: "Quando le stagioni arrivano, i nostri cuori fioriranno,"
          },
          {
            lineId: 2,
            en: "Every petal within shines bright and true,",
            it: "Ogni petalo splende, chiaro e sincero"
          },
          {
            lineId: 3,
            en: "Plenty will flourish deep in our hearts,",
            it: "Nel profondo dei cuori sboccerà l’abbondanza."
          },
          {
            lineId: 4,
            en: "We will bear the mark of Roses of Rome.",
            it: "Porteremo il segno delle Rose di Roma."
          }
        ]
      },
      {
        type: "chorus",
        verse: [
          { lineId: 5, en: "Roses of Rome,", it: "Rose di Roma," },
          {
            lineId: 6,
            en: "Let us bloom forever,",
            it: "Fioriamo per sempre,"
          },
          { lineId: 7, en: "Roses of Rome,", it: "Rose di Roma," },
          {
            lineId: 8,
            en: "May we always be with you, ever.",
            it: "Che possiamo sempre essere con te, per sempre."
          }
        ]
      },
      {
        type: "verse",
        verse: [
          {
            lineId: 9,
            en: "Though time may fade the colors we wear,",
            it: "Anche se il tempo potrà sbiadire i colori che indossiamo,"
          },
          {
            lineId: 10,
            en: "Our roots stand firm where glory finds its home,",
            it: "Le nostre radici restano salde dove la gloria dimora."
          },
          {
            lineId: 11,
            en: "Through every tear, joy, and whispered prayer —",
            it: "Attraverso ogni lacrima, gioia e preghiera sussurrata —"
          },
          {
            lineId: 12,
            en: "We still remain the Roses of Rome.",
            it: "Siamo ancora le Rose di Roma."
          }
        ]
      },
      {
        type: "verse",
        verse: [
          {
            lineId: 17,
            en: "So when we part, let memory sing,",
            it: "E quando ci separeremo, che la memoria canti."
          },
          {
            lineId: 18,
            en: "A love immortal carved in stone,",
            it: "Un amore immortale scolpito nella pietra,"
          },
          {
            lineId: 19,
            en: "With every breath, in every spring—",
            it: "Con ogni respiro, in ogni primavera—"
          },
          {
            lineId: 20,
            en: "We still remain the Roses of Rome.",
            it: "Siamo ancora le Rose di Roma."
          }
        ]
      }
    ]
  };
  return sonnet;
}
